// NOVEL (hand-authored) — not generated by CLI Printing Press.
//
// N131.5.5 review F-5: OpenReadOnlyContext backs the MCP `sql` and `search`
// tools (internal/mcp/tools.go openMCPReadOnlyStore). While it opened with
// immutable=1 it could not see WAL frames a still-open writer had committed
// but not checkpointed — a clean wrong answer, not an error: a missing row,
// and "no such table" for a table that exists only in those frames. The live
// archive is a WAL database and `history` holds the writer open for the whole
// fill, so the wrong answer is reachable in normal use.
//
// The fixture is the one the round-1 review measured: wal_autocheckpoint=0 so
// the commit stays in the -wal, and the writing connection is held open for
// the whole test so its close cannot checkpoint either.

package store

import (
	"context"
	"database/sql"
	"os"
	"path/filepath"
	"testing"
)

// openWALWriter returns a single-connection read-write handle in WAL mode with
// automatic checkpointing switched off.
func openWALWriter(t *testing.T, path string) *sql.DB {
	t.Helper()
	db, err := sql.Open("sqlite", "file:"+path+"?_pragma=busy_timeout(5000)")
	if err != nil {
		t.Fatalf("open writer: %v", err)
	}
	// One connection only: the pragmas below are per-connection state.
	db.SetMaxOpenConns(1)
	t.Cleanup(func() { _ = db.Close() })
	for _, pragma := range []string{"PRAGMA journal_mode=WAL", "PRAGMA wal_autocheckpoint=0"} {
		if _, err := db.Exec(pragma); err != nil {
			t.Fatalf("%s: %v", pragma, err)
		}
	}
	var mode string
	if err := db.QueryRow("PRAGMA journal_mode").Scan(&mode); err != nil {
		t.Fatalf("reading journal_mode: %v", err)
	}
	if mode != "wal" {
		t.Fatalf("fixture must be WAL, got %q", mode)
	}
	return db
}

func walBytes(t *testing.T, path string) int64 {
	t.Helper()
	fi, err := os.Stat(path + "-wal")
	if err != nil {
		return 0
	}
	return fi.Size()
}

func TestOpenReadOnlyContextSeesAnUncheckpointedWALCommit(t *testing.T) {
	path := filepath.Join(t.TempDir(), "wal.db")
	writer := openWALWriter(t, path)

	if _, err := writer.Exec(`CREATE TABLE rows_under_test (n INTEGER)`); err != nil {
		t.Fatalf("create: %v", err)
	}
	if _, err := writer.Exec(`INSERT INTO rows_under_test (n) VALUES (1)`); err != nil {
		t.Fatalf("first insert: %v", err)
	}
	if _, err := writer.Exec(`PRAGMA wal_checkpoint(TRUNCATE)`); err != nil {
		t.Fatalf("checkpoint: %v", err)
	}
	// Committed after the checkpoint and never checkpointed: this row lives
	// only in the -wal while the writer stays open.
	if _, err := writer.Exec(`INSERT INTO rows_under_test (n) VALUES (2)`); err != nil {
		t.Fatalf("second insert: %v", err)
	}
	if size := walBytes(t, path); size == 0 {
		t.Fatalf("fixture is not exercising the WAL: %s-wal is %d bytes", path, size)
	}

	db, err := OpenReadOnlyContext(context.Background(), path)
	if err != nil {
		t.Fatalf("OpenReadOnlyContext: %v", err)
	}
	defer db.Close()

	var count int
	if err := db.db.QueryRow(`SELECT count(*) FROM rows_under_test`).Scan(&count); err != nil {
		t.Fatalf("counting rows through the read-only handle: %v", err)
	}
	if count != 2 {
		t.Fatalf("read-only handle saw %d rows, want 2: a committed WAL frame is invisible to it", count)
	}
}

func TestOpenReadOnlyContextSeesATableThatLivesOnlyInTheWAL(t *testing.T) {
	path := filepath.Join(t.TempDir(), "wal.db")
	writer := openWALWriter(t, path)

	if _, err := writer.Exec(`CREATE TABLE anchor (n INTEGER)`); err != nil {
		t.Fatalf("create anchor: %v", err)
	}
	if _, err := writer.Exec(`PRAGMA wal_checkpoint(TRUNCATE)`); err != nil {
		t.Fatalf("checkpoint: %v", err)
	}
	// Schema change that exists only in the un-checkpointed WAL.
	if _, err := writer.Exec(`CREATE TABLE later_table (n INTEGER)`); err != nil {
		t.Fatalf("create later_table: %v", err)
	}
	if _, err := writer.Exec(`INSERT INTO later_table (n) VALUES (7)`); err != nil {
		t.Fatalf("insert: %v", err)
	}

	db, err := OpenReadOnlyContext(context.Background(), path)
	if err != nil {
		t.Fatalf("OpenReadOnlyContext: %v", err)
	}
	defer db.Close()

	var n int
	if err := db.db.QueryRow(`SELECT n FROM later_table`).Scan(&n); err != nil {
		t.Fatalf("reading a table that exists: %v", err)
	}
	if n != 7 {
		t.Fatalf("read-only handle read n = %d, want 7", n)
	}
}

// The read-only handle stays read-only: query_only(true) refuses a write even
// though immutable=1 is gone.
func TestOpenReadOnlyContextRefusesAWrite(t *testing.T) {
	path := filepath.Join(t.TempDir(), "wal.db")
	writer := openWALWriter(t, path)
	if _, err := writer.Exec(`CREATE TABLE rows_under_test (n INTEGER)`); err != nil {
		t.Fatalf("create: %v", err)
	}

	db, err := OpenReadOnlyContext(context.Background(), path)
	if err != nil {
		t.Fatalf("OpenReadOnlyContext: %v", err)
	}
	defer db.Close()

	var queryOnly int
	if err := db.db.QueryRow(`PRAGMA query_only`).Scan(&queryOnly); err != nil {
		t.Fatalf("reading query_only: %v", err)
	}
	if queryOnly != 1 {
		t.Fatalf("query_only = %d, want 1", queryOnly)
	}
	if _, err := db.db.Exec(`INSERT INTO rows_under_test (n) VALUES (3)`); err == nil {
		t.Fatal("insert through the read-only handle succeeded; it must be refused")
	}
}
